import{_ as p,c as e,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"革","description":"高島易斷 - 革","frontmatter":{"title":"革","description":"高島易斷 - 革"},"headers":[],"relativePath":"classics/takashima/049.md","filePath":"classics/takashima/049.md"}'),i={name:"classics/takashima/049.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="革" tabindex="-1">革 <a class="header-anchor" href="#革" aria-label="Permalink to “革”">​</a></h1><h2 id="革-1" tabindex="-1">革 <a class="header-anchor" href="#革-1" aria-label="Permalink to “革”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>革：己日乃孚。元亨利貞，悔亡。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《革》，改革也。日者《離》象，納甲，《離》納己，己為土，位居中。《易》道貴乎得中，過中則變，古人以已有變更之義。《儀禮》，“少牢饋食禮，日用丁己”，鄭注，“必丁己者，取其自丁寧、自變己（更）”，（本書認為應讀為己，為一家之見更），是已有革義也。五常以土為信，土即己也。將有改革，先示以信，“己日”者，為信孚於人之日也，故曰“己日乃孚”。《離》火生於《乾》二，《兌》金生於《乾》四，是卦從《乾》來，故“元亨利貞”四德皆具。有孚“悔亡”，己日之功也。王弼曰，“即日不孚，已日乃孚，已讀作‘已事遄往’之已”，《疏》與《正義》，皆從其說。然《易》中用甲，用庚，用日，用月，各有精義，王說恐未然。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>澤中有火，革。君子以治歷，明時。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>澤本有水之所，變而有火，是亦天地之變象也，故曰《革》。君子法之，“治歷”者，推日月星辰之遷易，“明時”者，察分至寒暑之往來，故曰“君子以治歷明時”。歷者，天事也，時者，人事也，是順天道而治人事也。晝夜為一日之革，晦望為十月之革，分至為一歲之革，即《彖》所云“天地革而四時成”之義也。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：譬如有水之處，忽而出火，是氣運之反常也，宜順時改變，乃吉。</p><p>○　問戰徵：屯兵之地，防溪谷林木間著火，最宜謹慎。</p><p>○　問營商：《兌》為金，金入火則金熔矣，消耗之象。宜遷地貿易，乃可無咎。</p><p>○　問功名：龍門變化，燒尾之象，吉。</p><p>○　問婚姻：卦體上澤下火，澤有火，是水被火所制，夫為妻所制也。革者有出妻改娶之象。</p><p>○　問家宅：此宅防有火災，急宜改遷。</p><p>○　問疾病：是腎水枯涸，肝火上炎之症，宜改延良醫，順時調養。</p><p>○　問訟事：此事本無中生有，災自外來。宜改易訟詞，揆度時日，其辯自明，其訟得直。</p><p>○　問六甲：生女。凡佔此卦，皆女象，惟出月過時，變則成男。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>《離》為黃牛，《革》為牛皮，“鞏”，揚子《方言》謂，“火幹也”，是皮方去毛，以火幹之，猶未成其《革》也。初居《離》之始，其象如之。革者本大有為之事，初爻卑下，其時其地，皆未當革，其才與德，亦不足以任革，恰如取黃牛之革，始用《離》火以乾燥之而已，未可躁急而妄改也。《象傳》以“不可以有為”釋之，謂不可先時而革也。</p><h2 id="初九佔" tabindex="-1">初九佔 <a class="header-anchor" href="#初九佔" aria-label="Permalink to “初九佔”">​</a></h2><p>○　問時運：好運初來，猶宜固守，不可妄動。</p><p>○　問營商：商業初成，宜先立鞏固之基，未可妄事更張也。</p><p>○　問功名：初出求名，其才未充，其時尚早，必待四五年後，方能變化騰達。</p><p>○　問婚姻：男女之年尚幼，未可擬親，俟三年後，可以成就。</p><p>○　問家宅：此宅新造，屋宇堅固。</p><p>○　問疾病：病是胃火微弱，脾土過強，致中腹脹硬，有類黃疸之症。藥宜消積健脾以治之。</p><p>○　問訟事：必是健訟，未易斷結。</p><p>○　問六甲：生女。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>某友來，為攝綿土生意，願出資金，與餘合業，請卜一卦，以決盈虧。筮得《革》之《鹹》。</p><p>斷曰：卦體澤上火下，澤本為水土之合，火又能生土，《革》者，合水火以革土也，其象與製造攝綿土，適相符合。佔得初爻，為生意在發靭之始，爻辭曰“鞏用黃牛之革”。黃，中央之色，牛屬土，“革”皮也，土之外面，亦稱皮，“鞏”，堅韌也。攝綿土者，取粘土，和石灰，入灶，用火煅煉，其中有水有土有火，合三者而《革》成之也。初爻事在始謀，猶未可遽用其革，第示其象之堅韌，如牛革然。就爻而推論之，閱一年而革可行，閱二年而革可成，四年人皆信用其革，五六年則革成之晶，愈精愈美。初時所云牛皮，後皆為虎豹，而有文采矣。爻辭詳明切合，可信可喜。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>二為內卦之主，居《離》之中，《彖》所云“己日乃孚”，二實當之。在《彖》曰“乃孚”，是天人先期其孚也；在爻日“乃革”，是時會適當可革也。既“孚”“乃革”，不言孚而孚在其中矣。二與五應，“徵”者，往也，謂往應大人之命，以共啟文明之運，故吉而“無咎”。《象傳》以“行有嘉”釋之，《離》為火，火主禮，凡國家變革之事，要不外製禮之大法，《周禮·大宗伯》所謂“嘉禮親萬民”者，此也，故曰“行有嘉”也。</p><h2 id="六二佔" tabindex="-1">六二佔 <a class="header-anchor" href="#六二佔" aria-label="Permalink to “六二佔”">​</a></h2><p>○　問時運：行土運可以興事立業，大佳。</p><p>○　問戰徵：宜擇戊己日，行軍接戰，必可獲勝。</p><p>○　問營商：於攝綿土生意最宜。凡新立買賣，必擇土日開市大吉。</p><p>○　問功名：戊年或交土運必可成名。</p><p>○　問婚姻：可稱嘉偶。</p><p>○　問家宅：修理舊宅，宜擇土日。</p><p>○　問行人：戊己日可歸。</p><p>○　問疾病：逢己日可愈，吉。</p><p>○　問六甲：生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>縉紳某來，請佔氣運，筮得《革》之《夬》。</p><p>斷曰：卦名曰《革》，去舊取新，重興事業之象。卜得二爻，其地位在適當改革之時，知足下氣運正盛，大可有為。“徵吉”，徵，往也。二應在五，五在外卦，謂當往外而從五，自能獲吉。“己日”者，宜擇戊己日起行，前往無咎。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>三、四、五三爻，皆言“有孚”，是就《彖傳》“乃孚”之辭，至再至三，而申明告示，以期其孚也。三處《離》之終，二既行《革》，則革之成敗，正於三見之。操切行革，反以招敗，故“徵兇”；革當大事，革而不從，適以啟禍，故“貞厲”。是驟革者危，不革亦危也。君子惟先求其孚而已，是以革之事未行，革之言先布，《離》為言，當《離》三爻，故為“三就”。昔盤庚遷殷，周公之告多方多士，皆反覆詳明，不嫌其言之煩，惟期其民之孚也。言既“三就”，則我之誠意，可深入於民心，民於此時，當必“有孚攣如”矣。或雲“三就”者，如《左傳》所云：“政不可不慎，務三而已，一擇人，二因民，三從時。得此三者，而天人交孚矣。”其說亦通。《象傳》以“又何之”釋之，凡佔象如《乾》之《坤》，“之”字皆作變解，謂“三就”而革，復有何變也。</p><h2 id="九三佔" tabindex="-1">九三佔 <a class="header-anchor" href="#九三佔" aria-label="Permalink to “九三佔”">​</a></h2><p>○　問時運：當此有事之秋，一不謹慎，則有兇危立至，宜再三籌度而行，方得眾人信服。從此而往，時運大佳。</p><p>○　問戰徵：兵，凶事也，危事也，發軍之日，先宜號令申明，斯信則人任，往無不利也。</p><p>○　問營商：未計其盈，宜先防其虧。貿易之道，以信為主，必得眾商信從，乃可獲利。</p><p>○　問功名：必三試可就。</p><p>○　問婚姻：得三人為媒，可成。</p><p>○　問家宅：宜三遷。</p><p>○　問訟事：始審再審至大審，三審乃直。</p><p>○　問疾病：症象本危，三日後可愈。</p><p>○　問六甲：生女。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>某舊藩士，來請佔藩政方向，筮得《革》之《隨》。</p><p>斷曰：此卦澤水在上，《離》火在下，火盛則滅水，水盛則滅火。《彖傳》曰，“水火相息”，息或作滅，亦作生，滅而復生，是即去舊取新之義也，故謂之《革》。今佔得三爻，三以陰居陽，處《離》之終，按數成於三，三爻為適當革事之成，一革以後，為兇為吉，亦在三爻，知藩政之成敗，即在三爻時也。“革言”者，謂用革之議也；“三就”者，謂再三酌議而行之也。如是則人心信從，而革乃無咎，否則驟革固兇，不革亦危，是明示藩政之不可不革，而亦不可驟用其革也，足下其審慎！</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>革而議之謂之言，革而行之謂之命。四爻出《離》入《兌》，當改革之交，《彖》曰“革而當，其悔乃亡”，四得專之。《兌》二曰“孚兌，吉”，《象傳》謂“孚兌之吉，信志也”，四爻曰“有孚吉”，而《象》亦曰“信志”，謂舉大事，動大眾，必先得民心，而後可大得志也。是《革》四爻，即《兌》二爻，故其辭同，其象亦同。“改命”者，必上膺天命，下順人心，鼎革一新，如湯武之革命是也。後世託言湯武，而妄思改命者，類皆滅亡，蓋革命必有湯武之志則吉，無湯武之志則兇，“改命”之吉，專指湯武而言。《象傳》曰“信志”，亦謂此也。</p><h2 id="九四佔" tabindex="-1">九四佔 <a class="header-anchor" href="#九四佔" aria-label="Permalink to “九四佔”">​</a></h2><p>○　問時運：曰“悔亡”，曰“吉”，是災悔既亡，而吉運來也。萬事皆可改作，無不如志。</p><p>○　問營商：必是舊業重興，大可得利。</p><p>○　問戰徵：改旗易轍，重振軍令，可以開國，可以闢地，可以轉敗為勝，吉。</p><p>○　問功名：改武就文，可以成名。</p><p>○　問婚姻：不利原聘，利重婚。</p><p>○　問家宅：改作改造，大吉大利。</p><p>○　問訟事：災悔已退，訟即可罷。</p><p>○　問失物：可尋得之。</p><p>○　問六甲：生女。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>友人某來，請佔氣運，筮得《革》之《既濟》。</p><p>斷曰：革者去故取新之卦，在人則衰運去而盛運來也。今佔得四爻，知足下之氣運方盛，從前災悔已消，此後事業重新，進而謀事，成就無疑。但不利仍舊，惟利改作，故曰“改命”。“命”，命運也，人生命運，五年一換。《彖》取“己日”，以土為用，信亦為土，如丙子運後，換入丁丑，土運正旺，故吉。凡平素不利之事，一經改革，無往不利矣。後果然。</p><p>明治二十八年一月三十一日，我軍陷威海衛，清國北洋艦隊，據守劉公島，抗拒我軍。二月五日，筮得《革》之《既濟》。</p><p>此卦我為內卦，屬《離》火，清為外卦，屬《兌》金，有以火鑠金之象。卦名曰《革》，革者改也，四爻正當變革之時，以火器攻打鐵艦，是全勝之佔也。後果以水雷擊沉艨艦，至十二日，北洋艦隊悉敗，炮臺亦歸我有。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>五爻得《坤》氣，《坤》為虎，《兌》屬正西，白虎西方之宿，故五爻有虎象。“虎變”者，虎之毛羽，變而成文，愈變而愈美者也。五居尊位，故稱“大人”，為《革》之主，風虎雲龍，變化莫測，為《革》之至盛至當者也，“湯武革命”，即在此爻。“未佔有孚”者，大人德位俱隆，躬任製作，將為天下更新，大啟文明之化，而天下之被其化者，早巳輸誠悅服，不敢或後，所謂不疑何卜？無容質諸於鬼神，故曰孚在佔先也。孚於人，尤孚於天，是天與之，人歸之，有見其孚而不見其革者矣。上互《乾》，《乾》為大人，非“乾道變化，各正性命”之大人，曷克臻此？《象傳》以“文炳”釋之，五處《兌》之中，兌為澤，為金，澤謂潤澤而有文也，金亦有文象，下應《離》火，《離》為光，為明，其文更著。丙火為《離》，丙即炳，故炳字，從火從丙。</p><h2 id="九五佔" tabindex="-1">九五佔 <a class="header-anchor" href="#九五佔" aria-label="Permalink to “九五佔”">​</a></h2><p>○　問時運：如此大運，非“首出庶物”之大人，不克當此。若常人佔得此爻，必能光前裕後，大振家聲。</p><p>○　問戰徵：虎臣桓桓，威聲早著，可不戰而來降也。</p><p>○　問營商：白虎屬西方之宿，西屬秋，防貨價至秋，大有變動。宜先訂定價，自可獲利，吉。</p><p>○　問功名：《乾》曰“雲從龍，風從虎”，言各得其際會也，吉。</p><p>○　問婚姻：俗以白虎為不利，婚事未佔先孚，猶言未嫁而先從也，為女不貞之象。</p><p>○　問家宅：虎動，亦不利。</p><p>○　問疾病：虎屬寅，寅為木，是必肝木振動之症。不佔先孚，必不藥而癒也，吉。</p><p>○　問六甲：象本生女，一變則為男。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>有某諸侯，使其庶子嗣末家，末家者幕府旗下之士也。戊辰之變，旗下之徒數百人，推末家為隊長，將謀舉事，其家臣五十餘人，多與其謀。於是本家憂之，遣使促歸，且曰若不歸藩，恐朝廷有疑於本藩，禍將不測。於是議論紛起，判成兩黨，一在促歸，一在不歸，迄將一月，議終不決。一日使人招餘，餘應招而往，兩黨數百之士，充滿藩邸，各述其意，餘皆聞之，曰：今日所謀之事，實國家之大事也，國家之大事，關夫天數，非可以私心判決者也。不如問諸《易》佔，眾鹹以為是，乃筮得《革》之《豐》。</p><p>斷曰：此卦可謂適切今日之事者也。今日諸君之所論，一欲盡忠於幕府，一欲奉朝命而為國，非即《彖》所云“二女同居，其志不相得”者乎？在僕觀之，卦名曰《革》，是明示以用革之象。爻為君位，辭曰“大人虎變”，“大人”者，謂應天承運之大人。虎為百獸之長，“變”，即革也，明示其人為當革之人，其時為革之時。時既當革，安得不應天順人，以應其革乎？諸君之論，半皆泥於仍舊，不知卦象，專在去舊取新，故知仍舊者非，故有慮革之而民弗信，不知二爻三爻，皆曰“有孚”，當未革而先期其孚，至五則革道已成矣，故曰“未佔有孚”。且經此一革，不特大受信用，且將率天下之民，日進於文明之化，行見重熙累洽，光被四表，即可見於此日了。宜速去此地，以歸本藩，是僕所得天數之占斷也。兩黨之士，聞之皆愕然，無敢出一辭，於是主君大嘉餘之占斷，即日整裝而歸。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>上爻居卦之極，有德無位，必是去位之賢大夫也，故稱“君子”。豹飾，大夫之服，故曰“豹變”。蓋革之成，始於四，整於五，終於上，是以五之聖君，既得顯虎文之燦，而上之大夫，亦得增“豹變”之華。“小人”，細民也，“面”者，向也，“革面”者，向化也，言小人皆潛移默化，於光天之下，革面洗心，欣欣然而有喜色也，是之謂“小人革面”。“徵兇”者，上與三應，上之“徵兇”，亦即三之“徵兇”也。謂大變既定，若復紛更自取多事，必如湯之昭德建中，惟期裕後，武之修文偃武，不復用兵，是即所謂居貞則吉也。《象傳》以“文蔚”釋之，“蔚”，深密之貌；豹隱處霧雨，欲澤其身，以成其文，猶言君子相與於文明之治，以增服飾之光也。</p><h2 id="上六佔" tabindex="-1">上六佔 <a class="header-anchor" href="#上六佔" aria-label="Permalink to “上六佔”">​</a></h2><p>○　問時運：運當全盛，光華顯著，惟宜守成，無事紛更。</p><p>○　問營商：創業以來，有名有利，已臻美備，此後宜知足謹守。</p><p>○　問功名：上居卦之終，功名早極，勸令功成身退，所謂“人死留名，豹死留皮”也。</p><p>○　問戰徵：軍用多取獸名，兕甲虎賁，皆用之以煥其文而揚其威也。上六爻已終，謂戰已定，宜罷兵退守，不可前往。</p><p>○　問婚姻：上與三應，九三陽也，上六陰也，三日“三就，有孚”，當再三逑合，自可成就，吉。</p><p>○　問家宅：爻位在上，其宅基必高。曰“徵兇”，知遷移不利；曰“居貞吉”，知居之得安也。</p><p>○　問失物：物已變革，尋亦不得。</p><p>○　問六甲：生女。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>縉紳某來，請佔氣運，筮得《革》之《同人》。</p><p>斷曰：此卦一變舊弊，改進文明之卦也。今佔得上爻，曰“君子豹變”，“君子”者，謂有德無位者也，豹亦為隱居之獸，正合貴下退位閒居之象也。想曩時贊襄維新之治，以成“虎變”之文，貴下固與有功焉。豹較虎而小，虎屬五爻為君，知豹變即指貴下。貴下之功績既著，文明亦顯，正可相與守成，無事多求，故曰“徵兇，居貞吉”。貴下之氣運如是，正可安亨納福。</p>',109)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
